-- Prompt 6C controlled Level 1 resource manifest. The temporary expected
-- relation is session-local and dropped at commit; no Drive identifier, URL,
-- permission, credential, or binary content is persisted.
create temporary table controlled_level_1_resources (
  id uuid primary key,
  academic_module_id uuid not null,
  resource_key text not null unique,
  source_relative_path text not null unique,
  display_name text not null,
  file_format text not null,
  mime_type text null,
  resource_classification text not null,
  distribution_review_status text not null,
  publication_state text not null,
  storage_object_path text null,
  source_modified_at timestamptz null
) on commit drop;

