insert into app.academic_module_resources (
  id, academic_module_id, resource_key, source_relative_path, display_name,
  file_format, mime_type, resource_classification, distribution_review_status,
  publication_state, storage_object_path, source_modified_at
)
select
  id, academic_module_id, resource_key, source_relative_path, display_name,
  file_format, mime_type, resource_classification, distribution_review_status,
  publication_state, storage_object_path, source_modified_at
from controlled_level_1_resources
on conflict do nothing;

do $$
begin
  if (select count(*) from app.educational_brands where (id, code, name, slug, status) in
      (('10000000-0000-4000-8000-000000000001'::uuid,'medway','Medway','medway','active'),
       ('10000000-0000-4000-8000-000000000002'::uuid,'elite','Elite','elite','active'),
       ('10000000-0000-4000-8000-000000000003'::uuid,'nexus','Nexus','nexus','active'))) <> 3
     or (select count(*) from app.academic_institutions where (id, code, display_name, slug, status) in
      (('15000000-0000-4000-8000-000000000001'::uuid,'buc','BUC','buc','active'),
       ('15000000-0000-4000-8000-000000000002'::uuid,'delta','Delta University','delta','active'))) <> 2
     or (select count(*) from app.brand_academic_institution_access where (brand_id, academic_institution_id, status) in
      (('10000000-0000-4000-8000-000000000001'::uuid,'15000000-0000-4000-8000-000000000001'::uuid,'active'),
       ('10000000-0000-4000-8000-000000000001'::uuid,'15000000-0000-4000-8000-000000000002'::uuid,'active'),
       ('10000000-0000-4000-8000-000000000002'::uuid,'15000000-0000-4000-8000-000000000001'::uuid,'active'),
       ('10000000-0000-4000-8000-000000000002'::uuid,'15000000-0000-4000-8000-000000000002'::uuid,'active'),
       ('10000000-0000-4000-8000-000000000003'::uuid,'15000000-0000-4000-8000-000000000001'::uuid,'active'),
       ('10000000-0000-4000-8000-000000000003'::uuid,'15000000-0000-4000-8000-000000000002'::uuid,'active'))) <> 6
     or (select count(*) from app.academic_levels where (id, academic_institution_id, level_number, display_title, sort_order, status) in
      (('20000000-0000-4000-8000-000000000001'::uuid,'15000000-0000-4000-8000-000000000001'::uuid,1,'Level 1',1,'active'),
       ('20000000-0000-4000-8000-000000000101'::uuid,'15000000-0000-4000-8000-000000000002'::uuid,1,'Level 1',1,'active'))) <> 2
     or (select count(*) from app.academic_semesters) <> 4
     or (select count(*) from (values
       ('30000000-0000-4000-8000-000000000001'::uuid,'20000000-0000-4000-8000-000000000001'::uuid,1,'Semester 1',1,'active'),
       ('30000000-0000-4000-8000-000000000002'::uuid,'20000000-0000-4000-8000-000000000001'::uuid,2,'Semester 2',2,'active'),
       ('30000000-0000-4000-8000-000000000101'::uuid,'20000000-0000-4000-8000-000000000101'::uuid,1,'Semester 1',1,'active')) v(id,level_id,semester_number,display_title,sort_order,status)
       join app.academic_semesters s on (s.id,s.academic_level_id,s.semester_number,s.display_title,s.sort_order,s.status)=(v.id,v.level_id,v.semester_number,v.display_title,v.sort_order,v.status)) <> 3
     or (select count(*) from app.academic_modules) <> 30
     or (select count(*) from app.academic_module_chapters) <> 98
     or (select count(*) from (values
       ('40000000-0000-4000-8000-000000000001'::uuid,'30000000-0000-4000-8000-000000000001'::uuid,'1101 TSF','1101 TSF',1101,'unreviewed'),
       ('40000000-0000-4000-8000-000000000002'::uuid,'30000000-0000-4000-8000-000000000001'::uuid,'1102 ANA','1102 ANA',1102,'unreviewed'),
       ('40000000-0000-4000-8000-000000000003'::uuid,'30000000-0000-4000-8000-000000000001'::uuid,'1103 CBG','1103 CBG',1103,'unreviewed'),
       ('40000000-0000-4000-8000-000000000004'::uuid,'30000000-0000-4000-8000-000000000001'::uuid,'1104 BIO','1104 BIO',1104,'unreviewed'),
       ('40000000-0000-4000-8000-000000000005'::uuid,'30000000-0000-4000-8000-000000000001'::uuid,'1105 PMD','1105 PMD',1105,'blocked'),
       ('40000000-0000-4000-8000-000000000006'::uuid,'30000000-0000-4000-8000-000000000001'::uuid,'1106 ECX','1106 ECX',1106,'unreviewed'),
       ('40000000-0000-4000-8000-000000000007'::uuid,'30000000-0000-4000-8000-000000000001'::uuid,'1107 SIM','1107 SIM',1107,'unreviewed'),
       ('40000000-0000-4000-8000-000000000008'::uuid,'30000000-0000-4000-8000-000000000002'::uuid,'1208 IPP','1208 IPP',1208,'unreviewed'),
       ('40000000-0000-4000-8000-000000000009'::uuid,'30000000-0000-4000-8000-000000000002'::uuid,'1209 PAT','1209 PAT',1209,'unreviewed'),
       ('40000000-0000-4000-8000-000000000010'::uuid,'30000000-0000-4000-8000-000000000002'::uuid,'1210 MIC','1210 MIC',1210,'unreviewed'),
       ('40000000-0000-4000-8000-000000000011'::uuid,'30000000-0000-4000-8000-000000000002'::uuid,'1211 PHE','1211 PHE',1211,'unreviewed'),
       ('40000000-0000-4000-8000-000000000012'::uuid,'30000000-0000-4000-8000-000000000002'::uuid,'1212 IMM','1212 IMM',1212,'unreviewed'),
       ('40000000-0000-4000-8000-000000000013'::uuid,'30000000-0000-4000-8000-000000000002'::uuid,'1213 SIM','1213 SIM',1213,'unreviewed'),
       ('40000000-0000-4000-8000-000000000014'::uuid,'30000000-0000-4000-8000-000000000002'::uuid,'1214 SBS','1214 SBS',1214,'unreviewed'),
       ('40000000-0000-4000-8000-000000000101'::uuid,'30000000-0000-4000-8000-000000000101'::uuid,'DELTA-ENG1','English 1',101,'unreviewed'),
       ('40000000-0000-4000-8000-000000000102'::uuid,'30000000-0000-4000-8000-000000000101'::uuid,'DELTA-IT','IT',102,'unreviewed')) v(id,semester_id,code,label,sort_order,review_status)
       join app.academic_modules m on (m.id,m.academic_semester_id,m.code,m.source_display_label,m.sort_order,m.review_status)=(v.id,v.semester_id,v.code,v.label,v.sort_order,v.review_status)) <> 16
     or (select count(*) from app.instructors where (id, code, display_name, status) in
      (('50000000-0000-4000-8000-000000000001'::uuid,'INS-00001','محمد بسيوني فايد','active'),('50000000-0000-4000-8000-000000000002'::uuid,'INS-00002','زياد وائل فتحي','active'),('50000000-0000-4000-8000-000000000003'::uuid,'INS-00003','شروق محمد عاطف','active'))) <> 3
     or (select count(*) from (values
       ('60000000-0000-4000-8000-000000000001'::uuid,'50000000-0000-4000-8000-000000000001'::uuid,'10000000-0000-4000-8000-000000000002'::uuid,'active'),
       ('60000000-0000-4000-8000-000000000002'::uuid,'50000000-0000-4000-8000-000000000002'::uuid,'10000000-0000-4000-8000-000000000002'::uuid,'active'),
       ('60000000-0000-4000-8000-000000000003'::uuid,'50000000-0000-4000-8000-000000000003'::uuid,'10000000-0000-4000-8000-000000000002'::uuid,'active')) v(id,instructor_id,brand_id,status)
       join app.instructor_brand_assignments a on (a.id,a.instructor_id,a.brand_id,a.status)=(v.id,v.instructor_id,v.brand_id,v.status)) <> 3 then
    raise exception using errcode = '23514', message = 'Controlled seed conflict.';
  end if;
end;
$$;

do $$
begin
  if (select count(*) from controlled_level_1_resources) <> 947
     or (select count(*)
         from controlled_level_1_resources e
         join app.academic_module_resources r
           on (r.id, r.academic_module_id, r.resource_key, r.source_relative_path,
               r.display_name, r.file_format, r.mime_type,
               r.resource_classification, r.distribution_review_status,
               r.publication_state, r.storage_object_path, r.source_modified_at)
              is not distinct from
              (e.id, e.academic_module_id, e.resource_key, e.source_relative_path,
               e.display_name, e.file_format, e.mime_type,
               e.resource_classification, e.distribution_review_status,
               e.publication_state, e.storage_object_path, e.source_modified_at)) <> 947
     or (select count(*)
         from app.academic_module_resources r
         where r.id in (select id from controlled_level_1_resources)
            or r.resource_key in (select resource_key from controlled_level_1_resources)
            or r.source_relative_path in (select source_relative_path from controlled_level_1_resources)) <> 947 then
    raise exception using errcode = '23514', message = 'Controlled Level 1 resource seed conflict.';
  end if;
end;
$$;

commit;
